$family=(Resolve-Path $PABuildRunPath).Path;$paManifest=Get-Content -LiteralPath (Join-Path $family 'run_manifest.json') -Raw -Encoding UTF8|ConvertFrom-Json;$paStatus=[string]$paManifest.status;if($paStatus-notin@('success','checkpoint')){throw 'Provider focus-PA manifest is neither reusable success nor retained runtime checkpoint'};& $python -I -B -c 'from msplatform.execution.manifest_verification import main; from msplatform.backends.simion.native_completion import retention_api; main(retention_api=retention_api)' (Join-Path $family 'run_manifest.json') --require-status $paStatus --require-project orthogonal_accelerator --require-mode component_focus_pa_build;if($LASTEXITCODE-ne0){throw 'Provider focus-PA manifest verification failed'}
$result=Get-Content -Raw (Join-Path $family 'results\component_focus_pa_result.json')|ConvertFrom-Json;$disposition=if($null-ne$result.PSObject.Properties['disposition']){[string]$result.disposition}else{''};$published=(@('published','hit')-contains$disposition)-or($result.status-eq'published'-and$result.action_required-eq'complete');if(-not$published){throw 'Focus PA is not a published cache generation'}
 $plan=Join-Path $family 'results\component_focus_pa_plan.json';if(-not(Test-Path $plan)){throw 'Provider focus PA plan is missing'};$planDocument=Get-Content -Raw $plan|ConvertFrom-Json -Depth 30;$electrodeCount=[int]$planDocument.electrode_count;$generation=(Resolve-Path $result.generation_directory).Path;$manifestPath=if(Test-Path -LiteralPath (Join-Path $generation 'cache_manifest.json')){Join-Path $generation 'cache_manifest.json'}else{Join-Path $generation 'focus_manifest.json'};$manifest=Get-Content -Raw $manifestPath|ConvertFrom-Json;$expectedNames=@('orthogonal_accelerator_focus.pa#')+@(0..$electrodeCount|ForEach-Object{"orthogonal_accelerator_focus.pa$_"})+@(1..$electrodeCount|ForEach-Object{"orthogonal_accelerator_focus.response$_.pa"})+@('orthogonal_accelerator_focus.standalone_responses.json');$expectedNames=@($expectedNames|Sort-Object);if((@($manifest.files|ForEach-Object{$_.name})-join ',')-ne($expectedNames-join ',')){throw 'Published provider cache inventory lacks its exact standalone response bank'};$controller=(Resolve-Path -LiteralPath $RuntimeControllerPath).Path;if([IO.Path]::GetFullPath($controller).StartsWith([IO.Path]::GetFullPath($generation)+[IO.Path]::DirectorySeparatorChar,[StringComparison]::OrdinalIgnoreCase)){throw 'Flight refuses a controller inside the published cache generation'};$runtimeDirectory=Split-Path -Parent $controller;$runtimeNames=@(Get-ChildItem -LiteralPath $runtimeDirectory -File|ForEach-Object{$_.Name}|Sort-Object);$expectedRuntimeNames=@(0..$electrodeCount|ForEach-Object{"orthogonal_accelerator_focus.pa$_"});if(($runtimeNames-join ',')-ne(($expectedRuntimeNames|Sort-Object)-join ',')){throw 'Private runtime family inventory differs from the provider electrode namespace'}
$campaign=(Resolve-Path -LiteralPath $CampaignPath).Path;$package=Get-Content -LiteralPath $PackagePath -Raw -Encoding UTF8|ConvertFrom-Json
try{$run=$package.run_dir;$inputs=$package.input_dir;$solver=Join-Path $run 'simion';$results=$package.result_dir;$logs=$package.log_dir
