 $campaignTemplate=Join-Path $inputs 'campaign_template.json';$runCampaign=Join-Path $inputs 'campaign.json';Copy-VerifiedRunInput $campaign $campaignTemplate|Out-Null;Copy-VerifiedRunInput $plan (Join-Path $inputs 'component_focus_pa_plan.json')|Out-Null;Copy-VerifiedRunInput (Join-Path $simionResources 'scientific_event_csv.lua') (Join-Path $solver 'component_focus.scientific_event_csv.lua')|Out-Null;Copy-VerifiedRunInput (Join-Path $simionResources 'component_focus.lua') (Join-Path $solver 'component_focus.lua')|Out-Null;Copy-VerifiedRunInput (Join-Path $simionResources 'build_component_focus_iob.lua') (Join-Path $solver 'build_component_focus_iob.lua')|Out-Null
 $releaseSpec=Join-Path $inputs 'release_spec.json';$c=Get-Content -Raw $campaignTemplate|ConvertFrom-Json;Copy-VerifiedRunInput (Resolve-Path -LiteralPath $ReleaseSpecPath).Path $releaseSpec|Out-Null;$c.release_spec=(Get-Content -Raw $releaseSpec|ConvertFrom-Json);$c|ConvertTo-Json -Depth 12|Set-Content $runCampaign -Encoding utf8;$p=Get-Content -Raw (Join-Path $inputs 'component_focus_pa_plan.json')|ConvertFrom-Json;$paSpan=@($p.numerical_domain.span_mm);$storedSpan=@($p.numerical_domain.stored_span_mm);if($paSpan.Count-ne3-or$storedSpan.Count-ne3){throw 'Provider PA span metadata is invalid'};for($i=0;$i-lt3;$i++){if([double]$paSpan[$i]-ne[double]$manifest.identity.grid_phase.pa_span_mm[$i]-or[double]$storedSpan[$i]-ne[double]$manifest.identity.grid_phase.stored_span_mm[$i]){throw 'Published PA span differs from provider plan'}};$resolvedProjection=$c.simion_projection.PSObject.Copy();$resolvedProjection.local_pa_span_mm=@($paSpan);$resolvedProjection.local_exit_z_mm=[double]$p.numerical_domain.local_exit_z_mm;$projectionPath=Join-Path $inputs 'resolved_projection.json';$resolvedProjection|ConvertTo-Json -Depth 12|Set-Content $projectionPath -Encoding utf8;$originX=[double]$p.numerical_domain.iob_origin_mm[0];$originY=[double]$p.numerical_domain.iob_origin_mm[1]+[double]$c.operating_point.instance_center_y_mm;$originZ=[double]$p.numerical_domain.iob_origin_mm[2];$focusPython=Initialize-FocusFrozenPython -PackageRoot $packageRoot -RunConfig $package.run_config -Python $python -CampaignPath $runCampaign -InputNames @('campaign_template.json','campaign.json','component_focus_pa_plan.json','release_spec.json','resolved_projection.json');$release=Join-Path $inputs 'release.csv';$releaseReceipt=Join-Path $inputs 'release_receipt.json';Invoke-FocusFrozenPython -Python $python -CodeRoot $focusPython.code_root -OriginsPath $focusPython.origins_path -Module msplatform.particle_release.cylinder -Arguments @('--materialize',$releaseSpec,'--state-table',$release,'--receipt',$releaseReceipt);if($LASTEXITCODE-ne0){throw 'Common ion release failed'}
 $fly=Join-Path $solver 'component_focus_input.fly2';$sourceStates=Join-Path $solver 'component_focus.source_states.lua';$sourceReceipt=Join-Path $results 'source_projection.json';Invoke-FocusFrozenPython -Python $python -CodeRoot $focusPython.code_root -OriginsPath $focusPython.origins_path -Module msplatform.backends.simion.oa_focus_source -Arguments @('--release-receipt',$releaseReceipt,'--campaign',$runCampaign,'--provider-plan',(Join-Path $inputs 'component_focus_pa_plan.json'),'--resolved-projection',$projectionPath,'--fly2',$fly,'--source-states',$sourceStates,'--receipt',$sourceReceipt);if($LASTEXITCODE-ne0){throw 'SIMION source projection failed'}
 $frozenConfig=Get-Content -LiteralPath $package.run_config -Raw -Encoding utf8|ConvertFrom-Json -AsHashtable;$frozenConfig.inputs['release.csv']=Join-Path (Split-Path -Parent $package.run_config) 'inputs/release.csv';$frozenConfig|ConvertTo-Json -Depth 100|Set-Content -LiteralPath $package.run_config -Encoding utf8
 $testPlaneLibrary=Join-Path (Split-Path -Parent $SimionExe) 'examples\test_plane\testplanelib.lua';if(-not(Test-Path -LiteralPath $testPlaneLibrary -PathType Leaf)){throw 'SIMION official test_plane library is required'};Copy-VerifiedRunInput $testPlaneLibrary (Join-Path $solver 'testplanelib.lua')|Out-Null
 $op=Join-Path $solver 'component_focus.operating_point.lua';$volts=($c.operating_point.electrode_voltages_v|ForEach-Object{[string]$_}) -join ',';@("return { voltages={ $volts }, field_mode='$FieldMode', trajectory_quality=$($c.numerics.trajectory_quality), maximum_step_us=$($c.numerics.maximum_step_us), particle_count=$($c.release_spec.particle_count), focus_plane_tolerance_mm=$($c.acceptance.focus_plane_tolerance_mm), local_exit_z_mm=$($p.numerical_domain.local_exit_z_mm), focus_plane_offset_from_exit_mm=$($c.operating_point.focus_plane_offset_from_exit_mm), focus_plane_local_z_mm=$($p.numerical_domain.focus_plane_local_z_mm), grid1_local_z_mm=$($p.layout.local_exit_z_mm + $p.layout.gap_2_mm), repeller_local_z_mm=$($p.layout.local_repeller_z_mm) }")|Set-Content $op -Encoding ascii
 $seed=Join-Path $simionResources '1_instance_seed.iob';$iob=Join-Path $solver 'component_focus.iob';&$SimionExe --nogui --noprompt lua (Join-Path $solver 'build_component_focus_iob.lua') -- $seed $controller $iob (Join-Path $solver 'component_focus.lua') $fly $originX $originY $originZ 2>&1|Tee-Object (Join-Path $logs 'iob_build.log');if($LASTEXITCODE-ne0){throw 'IOB build failed'}
 Push-Location $solver;try{&$SimionExe --nogui --noprompt fly --trajectory-quality $($c.numerics.trajectory_quality) --particles $fly --programs 1 --retain-trajectories 0 $iob 2>&1|Tee-Object (Join-Path $logs 'focus.log');if($LASTEXITCODE-ne0){throw 'SIMION flight failed'}}finally{Pop-Location}
