 $analysis=Join-Path $results 'focus_analysis.json';Invoke-FocusFrozenPython -Python $python -CodeRoot $focusPython.code_root -OriginsPath $focusPython.origins_path -Module msplatform.workflows.oa_focus_analysis -Arguments @('--component-contract',(Join-Path $focusPython.code_root 'src/msplatform/components/orthogonal_accelerator/component_contract.json'),'--events',$events,'--release-receipt',$releaseReceipt,'--campaign',$runCampaign,'--output',$analysis);$analysisExit=$LASTEXITCODE;if($analysisExit-ne0-and-not(Test-Path -LiteralPath $analysis)){throw 'Component focus analysis did not produce evidence'};$analysisResult=Get-Content -Raw $analysis|ConvertFrom-Json;if($analysisResult.status-notin@('candidate_complete','candidate_incomplete')){throw 'Component focus analysis status is invalid'}
 $storeAssetId=if($null-ne$result.PSObject.Properties['store_asset_id']){[string]$result.store_asset_id}else{''}
 $cacheManifest=if(Test-Path -LiteralPath (Join-Path $generation 'cache_manifest.json')){Join-Path $generation 'cache_manifest.json'}else{Join-Path $generation 'focus_manifest.json'}
 $summary=Join-Path $run 'summary.json';@{schema_version=1;role='orthogonal_accelerator_component_focus';status=[string]$analysisResult.status;qualification='candidate_prototype_numeric_component_focus_only';cache_key=$result.cache_key;generation_sha256=$result.generation_sha256;pa_build_run_manifest_sha256=(Get-FileHash (Join-Path $family 'run_manifest.json') -Algorithm SHA256).Hash;cache_manifest_sha256=(Get-FileHash $cacheManifest -Algorithm SHA256).Hash;store_asset_id=$storeAssetId;runtime_controller_path=$controller;runtime_controller_bytes=(Get-Item -LiteralPath $controller).Length;pa_cache_policy='published_standalone_responses__shared_private_native_fast_adjust_family'}|ConvertTo-Json|Set-Content $summary -Encoding utf8
 $outputs=@($summary,$analysis,$focusPython.origins_path,$sourceReceipt,$releaseReceipt,$fly,$sourceStates,$iob,$events,(Join-Path $logs 'focus.log'),(Join-Path $solver 'component_focus.lua'),(Join-Path $solver 'component_focus.scientific_event_csv.lua'),(Join-Path $solver 'component_focus.operating_point.lua'),(Join-Path $solver 'testplanelib.lua'))
 Write-RunJson -Path (Join-Path $results 'action_publication.json') -Depth 8 -Value ([ordered]@{schema_version=1;role='oa_focus_action_publication';outputs=$outputs})
}catch{throw
